const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const donnerPass = ee.Geometry.Point([-120.32, 39.31]); // Donner Pass coordinates
  const feb2022 = ee.DateRange('2022-02-01', '2022-02-28');
  const apr2022 = ee.DateRange('2022-04-01', '2022-04-30');

  // 2. Data Acquisition - NASA NLDAS Snow Water Equivalent
  const sweCollection = ee.ImageCollection('NASA/NLDAS/FORA0125_H002')
    .select('SWE_0_200cm'); // Snow water equivalent band

  const febCollection = sweCollection.filterDate(feb2022);
  const aprCollection = sweCollection.filterDate(apr2022);

  // Check collection sizes
  const febSize = febCollection.size().getInfo();
  const aprSize = aprCollection.size().getInfo();

  console.log(`February 2022 Images: ${febSize}`);
  console.log(`April 2022 Images: ${aprSize}`);

  if (febSize === 0 || aprSize === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Calculate mean SWE for each period
  const febMean = febCollection.mean();
  const aprMean = aprCollection.mean();

  // Get pixel counts and mean values
  const febStats = febMean.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: donnerPass,
    scale: 1000,
    maxPixels: 1e9
  });

  const aprStats = aprMean.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: donnerPass,
    scale: 1000,
    maxPixels: 1e9
  });

  const febResult = febStats.getInfo();
  const aprResult = aprStats.getInfo();

  const febSWE = febResult.SWE_0_200cm_mean;
  const febCount = febResult.SWE_0_200cm_count;
  const aprSWE = aprResult.SWE_0_200cm_mean;
  const aprCount = aprResult.SWE_0_200cm_count;

  console.log(`February SWE: ${febSWE !== null ? febSWE.toFixed(3) : 'null'}, Pixels: ${febCount}`);
  console.log(`April SWE: ${aprSWE !== null ? aprSWE.toFixed(3) : 'null'}, Pixels: ${aprCount}`);

  // 4. Validation & Final Answer
  if (febCount === 0 || aprCount === 0) {
    console.log("<answer>C2</answer>");
  } else if (febSWE === null || aprSWE === null || isNaN(febSWE) || isNaN(aprSWE)) {
    console.log("<answer>C3</answer>");
  } else if (febSWE > aprSWE) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
